const bootTarget = localStorage.getItem(LAST_TARGET_KEY) === 'workspace' ? 'workspace' : 'project';
if (bootTarget === 'workspace') setRunTarget('workspace');
// Boot: parse view + optional param so a reload on a deep link (#running/<id>)
